function CommonTipsBoardTeamNodeCell:FillTeam(go, data, ind,questType,excludeDialogs,_questId)
    if not go then
        return
    end
    --世界boss
    local isWorldBoss = (self._questType == Constants.IDType.QuestWorldBoss)
    KTool.SetActive(self.Other, not isWorldBoss)
    CfUtils.FillText(self.TextLevelName, "No."..ind)
    --世界boss
    if isWorldBoss then

    else
        CfUtils.SetUISwitchImage(self.ImgBgLevelName, ind)
        if data.teamTitle then
            CfUtils.FillText(self.TextLevelName, tostring(data.teamTitle))
        else
            local questId = data.questId
            if isNull(questId) then
                questId = self._questId
            end
            if questId  then
                local vo = QuestConfMgr:GetInstance():GetQuestVoById(questId)
                if vo then
                    CfUtils.FillText(self.TextLevelName, vo.name)
                end
            end
        end
    end

    --有数据  有卡牌数据代表有
    local cardInfo = data.cardInfo or data.cardsInfo
    if cardInfo then
        KTool.SetActive(self.Content, true)
        KTool.SetActive(self.WorldBossEmpty, false)
        CfUtils.FillText(self.TextNumberPower, checkNumber(data.combatValue))
        local catData = checkTable(data.catInfo)
        for i = 1, 2 do
            local catNode = self["CatBallNode"..i]
            if catNode then
                local hasCat = isNotNull(catData[i]) and isNotNull(catData[i].id)
                local catInfoNode = catNode.transform:Find("CommonSmallCatballNode")
                if catInfoNode then
                    KTool.SetActive(catInfoNode, hasCat and catData[i].id > 0)
                    if hasCat and catData[i].id > 0 then
                        local CatBallUtils                = import("Game.CatBall.CatBallUtils")
                        ---@type CatEggDojo
                        local catEggDojo    = CatBallUtils.GeneratedCatEggDojo(catData[i])
                        ---@type CatBallEntity
                        local catBallEntity = CatBallUtils.GeneratedCatBallEntity(catEggDojo)
                        CatBallUtils.FreshCommonSmallCatBallNode(catInfoNode, catBallEntity, function ()

                        end)
                    end
                end

                local noneNode = catNode.transform:Find("None")
                if noneNode then
                    KTool.SetActive(noneNode, not hasCat or not (catData[i].id > 0))
                end
            end
        end

        ---@type UITeamMembersNode
        local scr = CfUtils.GetLuaScr(self.UITeamMembersNode, UITeamMembersNode)
        if scr then
            if questType == Constants.IDType.QuestTrainField and not isNull(excludeDialogs) then
                --scr:FillTrainTestNode(cardInfo, 0.5, function(v)
                --    CommonTipsBoard.DestroySelf(self)
                --    print('===>>', questType, Constants.IDType.QuestTrainField, excludeDialogs)
                --    CardUtils.ShowCardPreview({ previewType = Constants.UICultivateCardPreviewType.Virtual, cardDojo = v }, excludeDialogs)
                --end)
                scr:FillTrainTestNode(cardInfo, 0.5, function()

                end)
            else
                scr:Refresh(cardInfo, false, 0.5, nil, nil, nil, true,_questId, true)
            end
        end
    else
        KTool.SetActive(self.Content, false)
        KTool.SetActive(self.WorldBossEmpty, true)
    end
end

